face.layout_source:
// dx7.face: the panel for tap/examples/synths/poly/dx7.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/synths/poly/dx7.face --meta <graph>.cragmeta

// Six operators of twelve controls each need a smaller knob.
knob.small { size: 28; }

face "DX7" {
  row(gap = 10) {
    box "Voice" {
      knob.big "Algorithm" (algorithm) knob "Feedback" (feedback) knob "Transpose" (transpose) knob "Rate Scale" (rate_scaling)
    }
    box "LFO" { knob "Speed" (lfo_speed) knob "Pitch" (lfo_pitch) }
    box "Output" (grow = 1) { knob.big "Volume" (volume) viz(grow = 1) }
  }
  row(gap = 10) {
    box "Operator 1" (cols = 6) {
      knob.small "Ratio" (op1_ratio) knob.small "Detune" (op1_detune) knob.small "Level" (op1_level) knob.small "Vel" (op1_velocity)
      knob.small "R1" (op1_r1) knob.small "R2" (op1_r2) knob.small "R3" (op1_r3) knob.small "R4" (op1_r4)
      knob.small "L1" (op1_l1) knob.small "L2" (op1_l2) knob.small "L3" (op1_l3) knob.small "L4" (op1_l4)
    }
    box "Operator 2" (cols = 6) {
      knob.small "Ratio" (op2_ratio) knob.small "Detune" (op2_detune) knob.small "Level" (op2_level) knob.small "Vel" (op2_velocity)
      knob.small "R1" (op2_r1) knob.small "R2" (op2_r2) knob.small "R3" (op2_r3) knob.small "R4" (op2_r4)
      knob.small "L1" (op2_l1) knob.small "L2" (op2_l2) knob.small "L3" (op2_l3) knob.small "L4" (op2_l4)
    }
    box "Operator 3" (cols = 6) {
      knob.small "Ratio" (op3_ratio) knob.small "Detune" (op3_detune) knob.small "Level" (op3_level) knob.small "Vel" (op3_velocity)
      knob.small "R1" (op3_r1) knob.small "R2" (op3_r2) knob.small "R3" (op3_r3) knob.small "R4" (op3_r4)
      knob.small "L1" (op3_l1) knob.small "L2" (op3_l2) knob.small "L3" (op3_l3) knob.small "L4" (op3_l4)
    }
  }
  row(gap = 10) {
    box "Operator 4" (cols = 6) {
      knob.small "Ratio" (op4_ratio) knob.small "Detune" (op4_detune) knob.small "Level" (op4_level) knob.small "Vel" (op4_velocity)
      knob.small "R1" (op4_r1) knob.small "R2" (op4_r2) knob.small "R3" (op4_r3) knob.small "R4" (op4_r4)
      knob.small "L1" (op4_l1) knob.small "L2" (op4_l2) knob.small "L3" (op4_l3) knob.small "L4" (op4_l4)
    }
    box "Operator 5" (cols = 6) {
      knob.small "Ratio" (op5_ratio) knob.small "Detune" (op5_detune) knob.small "Level" (op5_level) knob.small "Vel" (op5_velocity)
      knob.small "R1" (op5_r1) knob.small "R2" (op5_r2) knob.small "R3" (op5_r3) knob.small "R4" (op5_r4)
      knob.small "L1" (op5_l1) knob.small "L2" (op5_l2) knob.small "L3" (op5_l3) knob.small "L4" (op5_l4)
    }
    box "Operator 6" (cols = 6) {
      knob.small "Ratio" (op6_ratio) knob.small "Detune" (op6_detune) knob.small "Level" (op6_level) knob.small "Vel" (op6_velocity)
      knob.small "R1" (op6_r1) knob.small "R2" (op6_r2) knob.small "R3" (op6_r3) knob.small "R4" (op6_r4)
      knob.small "L1" (op6_l1) knob.small "L2" (op6_l2) knob.small "L3" (op6_l3) knob.small "L4" (op6_l4)
    }
  }
  keys(note_on, note_off)
}
